#include <stdio.h>
int main(){
    FILE *f = fopen("tmp.bin", "wb+");
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    char data[120] = {0};
    fwrite(data, 1, 120, f);
    fseek(f, 0, SEEK_SET);
    char buf[50];
    fread(buf, 1, 50, f);
    fseek(f, 0, SEEK_END);
    size = ftell(f);
    printf("%ld\n", size);
    fclose(f);
    return 0;
}
